<template><div class="page"><h2>巡检问题与整改</h2><div class="filters"><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option label="待整改" value="PENDING"/><el-option label="待复核" value="RECTIFIED"/><el-option label="已闭环" value="CLOSED"/></el-select></div><el-table :data="rows"><el-table-column prop="taskNo" label="任务编号"/><el-table-column prop="targetName" label="设备"/><el-table-column prop="fieldLabel" label="异常项目"/><el-table-column prop="description" label="问题说明" min-width="180"/><el-table-column label="级别"><template #default="s"><el-tag :type="s.row.level==='SERIOUS'?'danger':'warning'">{{s.row.level==='SERIOUS'?'严重':'警告'}}</el-tag></template></el-table-column><el-table-column label="状态"><template #default="s">{{statusText[s.row.status]||s.row.status}}</template></el-table-column><el-table-column label="操作" width="190"><template #default="s"><el-button v-if="s.row.status==='PENDING'" link type="primary" @click="rectify(s.row)">提交整改</el-button><el-button v-if="s.row.status==='RECTIFIED'" link type="success" @click="review(s.row,true)">复核通过</el-button><el-button v-if="s.row.status==='RECTIFIED'" link type="danger" @click="review(s.row,false)">退回</el-button></template></el-table-column></el-table></div></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{inspectionApi}from'@/api/inspection';const status=ref(''),rows=ref<any[]>([]),statusText:any={PENDING:'待整改',RECTIFIED:'待复核',CLOSED:'已闭环'};const unwrap=(r:any)=>r?.data?.data??r?.data??r;async function load(){rows.value=unwrap(await inspectionApi.issues({status:status.value||undefined}))}async function rectify(r:any){const x=await ElMessageBox.prompt('请填写整改结果','提交整改',{inputType:'textarea'});await inspectionApi.rectify(r.id,x.value);ElMessage.success('整改已提交');load()}async function review(r:any,p:boolean){await inspectionApi.review(r.id,p);ElMessage.success(p?'已闭环':'已退回整改');load()}onMounted(load)
</script><style scoped>.page{padding:20px}.filters{background:#fff;padding:12px;margin-bottom:12px}@media(max-width:768px){.page{padding:10px}}</style>
